      es: ["Fundada por los otomanos.", "Situada junto al río Tara.", "Centro para el esquí.", "Cualidades de balneario climático."],
      pt: ["Fundada pelos otomanos.", "Localizada junto ao rio Tara.", "Centro de esqui.", "Qualidades de estância climática."],
      fr: ["Fondée par les Ottomans.", "Située sur la rivière Tara.", "Centre pour le ski.", "Qualités de station climatique."],
